import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testStringIntPair() {
        val pair = Pair<String, Int>("Match", 7)
        Assert.assertEquals("Match", pair.first)
        Assert.assertEquals(7, pair.second)
    }

    @Test
    fun testToString() {
        val pair = Pair("Tribots", 4215)
        Assert.assertEquals("(Tribots, 4215)", pair.toString())
    }

    @Test
    fun testDoubleStringPair() {
        val pair = Pair(3.14, "pi")
        Assert.assertEquals(3.14, pair.first, 0.001)
        Assert.assertEquals("pi", pair.second)
    }

    @Test
    fun testIntIntPair() {
        val pair = Pair(10, 20)
        Assert.assertEquals("(10, 20)", pair.toString())
    }
}
